  1	/*Ex1 Given the leaky specification of class Set found in Appendix ??, use the techniques from
  2	class (the use of ghost state and dynamic frames) so that the specification no longer leaks
  3	the internal representation. Produce client code that correctly connects to your revised
  4	Set class. */
  5	
  6	class Set {
  7	  var store:array<int>;
  8	  var nelems: int;
  9	
 10	  ghost var Repr : set<object>
 11	  ghost var elems : set<int>
 12	
 13	
 14	  ghost predicate RepInv()
 15	    reads this, Repr
 16	  {
 17	    this in Repr && store in Repr &&
 18	    0 < store.Length
 19	    && 0 <= nelems <= store.Length
 20	    && (forall i :: 0 <= i < nelems ==> store[i] in elems)
 21	    && (forall x :: x in elems ==> exists i :: 0 <= i < nelems && store[i] == x)
 22	  }
 23	  // the construction operation
 24	  constructor(n: int)
 25	    requires 0 < n
 26	    ensures RepInv()
 27	    ensures fresh(Repr-{this})
 28	  {
 29	    store := new int[n];
 30	    Repr := {this,store};
 31	    elems := {};
 32	    nelems := 0;
 33	  }
 34	  // returns the number of elements in the set
 35	  function size():int
 36	    requires RepInv()
 37	    ensures RepInv()
 38	    reads Repr
 39	  { nelems }
 40	  // returns the maximum number of elements in the set
 41	  function maxSize():int
 42	    requires RepInv()
 43	    ensures RepInv()
 44	    reads Repr
 45	  { store.Length }
 46	  // checks if the element given is in the set
 47	  method contains(v:int) returns (b:bool)
 48	    requires RepInv()
 49	    ensures RepInv()
 50	    ensures b <==> v in elems
 51	  {
 52	
 53	    var i := find(v);
 54	    return i >= 0;
 55	  }
 56	  // adds a new element to the set if space available
 57	
 58	  method add(v:int)
 59	    requires size() < maxSize()
 60	    ensures RepInv()
 61	    modifies this,Repr
 62	    ensures fresh(Repr - old(Repr))
 63	  {
 64	    var f:int := find(v);
 65	    if (f < 0) {
 66	      store[nelems] := v;
 67	      elems := elems + {v};
 68	      assert forall i:: 0 <= i < nelems ==> old(store[i]) == store[i];
 69	      nelems := nelems + 1;
 70	    }
 71	  }
 72	  // private method that should not be in the
 73	  method find(x:int) returns (r:int)
 74	    requires RepInv()
 75	    ensures RepInv()
 76	    ensures r < 0 ==> x !in elems
 77	    ensures r >=0 ==> x in elems;
 78	  {
 79	    var i:int := 0;
 80	    while (i<nelems)
 81	      decreases nelems-i
 82	      invariant 0 <= i <= nelems;
 83	      invariant forall j::(0<=j< i) ==> x != store[j];
 84	    {
 85	      if (store[i]==x) { return i; }
 86	      i := i + 1;
 87	    }
 88	    return -1;
 89	  }
