207	/*
208	 * Implement a savings account.
209	 * A savings account is actually made up of two balances.
210	 *
211	 * One is the checking balance, here account owner can deposit and withdraw
212	 * money at will. There is only one restriction on withdrawing. In a regular
213	 * bank account, the account owner can make withdrawals as long as he has the
214	 * balance for it, i.e., the user cannot withdraw more money than the user has.
215	 * In a savings account, the checking balance can go negative as long as it does
216	 * not surpass half of what is saved in the savings balance. Consider the
217	 * following example:
218	 *
219	 * Savings = 10
220	 * Checking = 0
221	 * Operation 1: withdraw 10 This operation is not valid. Given that the
222	 * the user only has $$10, his checking account
223	 * can only decrease down to $$-5 (10/2).
224	 *
225	 * Operation 2: withdraw 2 Despite the fact that the checking balance of
226	 * the user is zero,
227	 * money in his savings account, therefore, this
228	 * operation is valid, and the result would be
229	 * something like:
230	 * Savings = 10;
231	 * Checking = -2
232	 *
233	 * Regarding depositing money in the savings balance (save), this operation has
234	 * one small restrictions. It is only possible to save money to the savings
235	 * balance when the user is not in debt; i.e. to save money into savings, the
236	 * checking must be non-negative.
237	 *
238	 * Given the states:
239	 * STATE 1 STATE 2
240	 * Savings = 10 Savings = 10
241	 * Checking = -5 Checking = 0
242	 *
243	 * and the operation save($$60000000000), the operation is valid when executed
244	 * in STATE 2 but not in STATE 1.
245	 *
246	 * Finally, when withdrawing from the savings balance, an operation we will
247	 * call rescue, the amount the user can withdraw depends on the negativity of
248	 * the user’s checking account. For instance:
249	 *
250	 * Savings: 12
251	 * Checking: -5
252	 *
253	 * In the case, the user could withdraw at most two double dollars ($$). If the
254	 * user withdrew more than that, the balance of the checking account would
255	 * go beyond the -50% of the savings account; big no no.
256	 *
257	 */
258	
259	class SavingsAccount {
260	
261	  var cbalance: int;
262	  var sbalance: int;
263	
264	  ghost var Repr:set<object>;
265	
266	  ghost predicate RepInv()
267	    reads this,Repr
268	  {
269	    this in Repr
270	    && cbalance >= -sbalance/2
271	  }
272	
273	  ghost predicate PositiveChecking()
274	    reads this,Repr
275	  {
276	    cbalance >= 0
277	  }
278	
279	  constructor()
280	    ensures fresh(Repr-{this})
281	    ensures RepInv()
282	  {
283	    Repr := {this};
284	    cbalance := 0;
285	    sbalance := 0;
286	  }
287	
288	  method deposit(amount:int)
289	    requires amount > 0
290	    requires RepInv()
291	    ensures RepInv()
292	    modifies Repr
293	  {
294	    cbalance := cbalance + amount;
295	  }
296	
297	  method withdraw(amount:int)
298	    requires amount > 0
299	    requires RepInv()
300	    ensures RepInv()
301	    modifies Repr
302	  {
303	    if(cbalance-amount >= -sbalance/2)
304	    {
305	      cbalance := cbalance - amount;
306	    }
307	  }
308	
309	  method save(amount: int)
310	    requires amount > 0
311	    requires PositiveChecking()
312	    requires RepInv()
313	    ensures RepInv()
314	    modifies Repr
315	  {
316	    if(cbalance >= 0)
317	    {
318	      sbalance := sbalance + amount;
319	    }
320	  }
321	
322	  method rescue(amount: int)
323	    requires amount > 0
324	    requires RepInv()
325	    ensures RepInv()
326	    modifies Repr
327	  {
328	
329	    if(cbalance >= -(sbalance-amount)/2)
330	    {
331	      sbalance := sbalance - amount;
332	    }
333	  }
334	}
