340	class GrowingSet {
341	  var store:array<int>;
342	  var nelems: int;
343	
344	  ghost var Repr : set<object>
345	  ghost var elems : set<int>
346	
347	
348	  ghost predicate RepInv()
349	    reads this, Repr
350	  {
351	    this in Repr && store in Repr &&
352	    0 < store.Length
353	    && 0 <= nelems <= store.Length
354	    && (forall i :: 0 <= i < nelems ==> store[i] in elems)
355	    && (forall x :: x in elems ==> exists i :: 0 <= i < nelems && store[i] == x)
356	  }
357	  // the construction operation
358	  constructor(n: int)
359	    requires 0 < n
360	    ensures RepInv()
361	    ensures fresh(Repr-{this})
362	  {
363	    store := new int[n];
364	    Repr := {this,store};
365	    elems := {};
366	    nelems := 0;
367	  }
368	  // returns the number of elements in the set
369	  function size():int
370	    requires RepInv()
371	    ensures RepInv()
372	    reads Repr
373	  { nelems }
374	  // returns the maximum number of elements in the set
375	  function maxSize():int
376	    requires RepInv()
377	    ensures RepInv()
378	    reads Repr
379	  { store.Length }
380	  // checks if the element given is in the set
381	  method contains(v:int) returns (b:bool)
382	    requires RepInv()
383	    ensures RepInv()
384	    ensures b <==> v in elems
385	  {
386	
387	    var i := find(v);
388	    return i >= 0;
389	  }
390	  // adds a new element to the set if space available
391	
392	  method add(v:int)
393	    requires RepInv()
394	    ensures RepInv()
395	    modifies Repr
396	    ensures fresh(Repr - old(Repr))
397	  {
398	    var f:int := find(v);
399	    assert forall i:: 0 <= i < nelems ==> old(store[i]) == store[i];
400	    if (f < 0) {
401	      if(nelems == store.Length) {
402	        var tmp := new int[store.Length * 2];
403	        var i:= 0;
404	        while i < store.Length
405	          invariant 0 <= i <= store.Length < tmp.Length
406	          invariant forall j :: 0 <= j < i ==> old(store[j]) == tmp[j]
407	          modifies tmp
408	        {
409	          tmp[i] := store[i];
410	          i := i + 1;
411	        }
412	        Repr := Repr - {store} + {tmp};
413	        store := tmp;
414	
415	      }
416	
417	      store[nelems] := v;
418	      elems := elems + {v};
419	      assert forall i:: 0 <= i < nelems ==> old(store[i]) == store[i];
420	      nelems := nelems + 1;
421	
422	    }
423	  }
424	  
