426	  method find(x:int) returns (r:int)
427	    requires RepInv()
428	    ensures RepInv()
429	    ensures r < 0 ==> x !in elems
430	    ensures r >=0 ==> x in elems;
431	  {
432	    var i:int := 0;
433	    while (i<nelems)
434	      decreases nelems-i
435	      invariant 0 <= i <= nelems;
436	      invariant forall j::(0<=j< i) ==> x != store[j];
437	    {
438	      if (store[i]==x) { return i; }
439	      i := i + 1;
440	    }
441	    return -1;
442	  }
